/**
 * The one daily brief (Gemini smart tier). Generated by the 07:30 cron, or the
 * first time Today opens on a new day; "Analyze now" re-reads everything
 * (projects, stages, tasks, client mail, portal messages) after you add data.
 */
import React, { useEffect, useState } from "react";
import { ChevronDown, Loader2, Mail, RefreshCw, Sparkles } from "lucide-react";
import { studioApi } from "../api";
import { useStudioOS } from "../StudioOSContext";

const AUTO_KEY = "sos-ai-brief-auto";

export const AIBriefCard: React.FC = () => {
  const { supabaseSyncStatus } = useStudioOS();
  const [brief, setBrief] = useState<any>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [open, setOpen] = useState(true);
  const [configured, setConfigured] = useState(true);

  const generate = async () => {
    setBusy(true);
    setError("");
    try {
      const j = await studioApi<any>("/api/studio-os/ai/brief", { method: "POST", body: {} });
      setBrief(j.brief);
    } catch (e: any) {
      setError(e?.message || "Couldn't build the brief");
    } finally {
      setBusy(false);
    }
  };

  useEffect(() => {
    if (supabaseSyncStatus !== "synced") return;
    let alive = true;
    (async () => {
      try {
        const j = await studioApi<any>("/api/studio-os/ai/brief");
        if (!alive) return;
        setConfigured(j.configured !== false);
        setBrief(j.brief);
        // First open of a new day with no brief yet → build it once.
        let last = "";
        try {
          last = localStorage.getItem(AUTO_KEY) || "";
        } catch {
          /* ignore */
        }
        if (j.configured !== false && j.brief?.day !== j.today && last !== j.today) {
          try {
            localStorage.setItem(AUTO_KEY, j.today);
          } catch {
            /* ignore */
          }
          generate();
        }
      } catch {
        /* offline */
      }
    })();
    return () => {
      alive = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [supabaseSyncStatus]);

  if (supabaseSyncStatus !== "synced" || !configured) return null;
  const b = brief?.result;
  const list = (title: string, rows: any[] | undefined, render: (r: any) => React.ReactNode, icon?: React.ReactNode) =>
    rows && rows.length > 0 ? (
      <div className="space-y-1">
        <p className="text-[11px] font-bold uppercase tracking-wider flex items-center gap-1" style={{ color: "var(--sos-text-3)" }}>
          {icon}
          {title}
        </p>
        {rows.map((r, i) => (
          <p key={i} className="text-[13px] leading-snug" style={{ color: "var(--sos-text-1)" }}>
            {r.project ? <span className="font-semibold sos-tabular mr-1" style={{ color: "var(--sos-primary)" }}>{r.project}</span> : null}
            {render(r)}
          </p>
        ))}
      </div>
    ) : null;

  return (
    <section className="sos-card p-5 md:p-6 space-y-3">
      <div className="flex items-center justify-between gap-2">
        <button type="button" onClick={() => setOpen(!open)} className="flex items-center gap-2.5 min-w-0 text-left">
          <span className="w-8 h-8 rounded-full flex items-center justify-center shrink-0" style={{ background: "var(--sos-surface-2)", color: "var(--sos-primary)" }}>
            <Sparkles className="w-4 h-4" />
          </span>
          <div className="min-w-0">
            <h2 className="sos-display text-[18px] font-semibold" style={{ color: "var(--sos-text-1)" }}>
              Today's brief
            </h2>
            {b && <p className="text-[13px] truncate" style={{ color: "var(--sos-text-2)" }}>{b.headline}</p>}
          </div>
          <ChevronDown className={`w-4 h-4 shrink-0 transition-transform ${open ? "rotate-180" : ""}`} style={{ color: "var(--sos-text-3)" }} />
        </button>
        <button type="button" disabled={busy} onClick={generate} className="sos-pill-btn h-9 px-3 text-[12px] font-semibold border inline-flex items-center gap-1.5 shrink-0 disabled:opacity-60" style={{ borderColor: "var(--sos-border)", color: "var(--sos-text-2)", background: "var(--sos-surface)" }} title="Re-read projects, tasks, mail and portal messages">
          {busy ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <RefreshCw className="w-3.5 h-3.5" />} Analyze now
        </button>
      </div>
      {error && <p className="text-[12px] px-3 py-2 rounded-[10px]" style={{ background: "#FDECEC", color: "#B42318" }}>{error}</p>}
      {!b && !busy && !error && <p className="text-[13px]" style={{ color: "var(--sos-text-3)" }}>Add clients and projects, then tap Analyze now — the brief reads everything, including client mail.</p>}
      {busy && !b && <p className="text-[13px]" style={{ color: "var(--sos-text-3)" }}>Reading projects, tasks, mail and portal messages…</p>}
      {b && open && (
        <div className="grid gap-4 md:grid-cols-2">
          {list("Focus today", b.focus, (r) => <>{r.title} <span style={{ color: "var(--sos-text-3)" }}>— {r.why}</span></>)}
          {list("Waiting on clients", b.waiting_on_client, (r) => <>{r.what}{r.since ? <span style={{ color: "var(--sos-text-3)" }}> · since {r.since}</span> : null}</>)}
          {list("Risks", b.risks, (r) => r.risk)}
          {list("Reply today", b.reply_today, (r) => <><b>{r.to}</b> — {r.about}</>)}
          {list("What the mail says", b.mail_status, (r) => <>{r.status_from_mail} <span style={{ color: "var(--sos-text-3)" }}>→ {r.suggested_update}</span></>, <Mail className="w-3 h-3" />)}
          {list("Mail not matched to a client", b.unmatched_mail, (r) => <>{r.subject} <span style={{ color: "var(--sos-text-3)" }}>({r.from}) → {r.suggestion}</span></>, <Mail className="w-3 h-3" />)}
        </div>
      )}
      {brief && open && (
        <p className="text-[11px]" style={{ color: "var(--sos-text-3)" }}>
          {brief.model} · {new Date(brief.created_at).toLocaleString()}
          {b?.counts ? ` · read ${b.counts.projects} projects, ${b.counts.mail} mail threads, ${b.counts.inbox} inbox items` : ""}
        </p>
      )}
    </section>
  );
};
